"""Destination `sas_restructured`: generated by package-factory from approved specs. Do not edit here.

Requirement (approved):
  Destination is the same S3 bucket as the source (region eu-north-1). Each package is one file whose path is relative to incoming/ (first folder = study ID, used exactly as written). Decide the target key from the folder path only (the path without the file name); the file name is always kept. Data format from the folder path: adam if it contains /adam/, otherwise sdtm if it contains /sdtm/, otherwise raw if it contains raw/ (so restricted_raw/ also counts as raw). For anonymised folders the data format comes from _adam_, _sdtm_, _raw_ or _restricted_raw_ (= raw). "Last folder" = the folder that directly contains the file. Check every rule; exactly one rule must match. 1. CDAP: path contains /data_reuse/ and /cdap_ and a data format. If it contains /cdap_csr -> {study}/extended_primary_use/primary/{format}/{file}. Else if the last folder contains _ia -> take the third "_" part of the last folder (cdap_20210617_ia300 -> ia300) and write it as ia_ + the rest (ia_300) -> {study}/extended_primary_use/interim/{format}/ia_300/{file}; fewer than 3 parts -> error. Else -> second "_" part of the last folder (cdap_20210617 -> 20210617) -> {study}/extended_primary_use/other/{format}/20210617/{file}; fewer than 2 parts -> error. 2. IDAP: path contains /data_reuse/ and /idap and a data format -> {study}/internal_reuse/{format}/{last folder}/{file}. 3. MED: path contains /data_reuse/ and /med and a data format -> {study}/external_reuse/{format}/{last folder}/{file}. 4. ANON: path contains _anon_ and an underscore data format. If it contains _anon_csr -> {study}/anonymised/primary/{format}/{file}. Else take the last "_" part of the last folder: if it starts with lowercase ia (case-sensitive, e.g. ia500) -> {study}/anonymised/interim/{format}/ia_500/{file}; otherwise (e.g. 20220120) -> {study}/anonymised/other/{format}/20220120/{file}. 5. CDAR: path contains /cdar/ and a data format. Reporting level = the folder right after the folder named "ar" (case-insensitive, compared in lowercase). No "ar" folder, or reporting level is adam, sdtm or raw -> error. csr -> {study}/primary/complete/{format}/{file}. Starts with ia -> remove "ia" and any leading "_", then add "ia_" (ia1 -> ia_1, ia_psc -> ia_psc) -> {study}/primary/interim/{format}/{ia_x}/{file}. Anything else (e.g. bdr200) -> {study}/primary/other/{format}/bdr200/{file}. 6. OTHERS: path contains /data_reuse/ and a data format, and none of /med, /cdap, /idap, /anon, _anon_ -> {study}/other/{format}/{last folder}/{file}. 7. DEFAULT (pass-through): path has none of /data_reuse/, _anon_, /cdar/ -> the same path (relative to incoming/, i.e. with incoming/ removed). If no rule matches, more than one rule matches, or the target cannot be worked out -> move the file to error/{path without incoming/}. Never drop a file. DELIVERY BEHAVIOUR: Move, not copy: copy server-side (files can exceed 5 GiB), confirm the target exists, then delete the source from incoming/. If the copy or the check fails, leave the source in incoming/ so the next run retries it; that file fails. An existing object at the target is overwritten. After a successful move, replace all tags on the target with exactly one tag: ADDITIONAL_TAG = the original path without incoming/. A tagging failure is only a warning (the file still counts as moved). Files moved to error/ get no tag change. Report one line per file: source, target, rule or error reason. The run fails only if a copy, check or delete failed. Moving files to error/ does not fail the run.
Plan approved by @jsandy16 at 2026-10-19T06:39:27+00:00
Code approved by @jsandy16 at 2026-10-19T11:24:32+00:00

Steps:
  1. compute_sas_keys [custom] Decide target key per file from folder path (7 rules, exactly one must match, else error/)
  2. deliver_move_with_tag [custom_delivery] Move each file in the bucket (server-side copy, check, delete source), tag target, report
Custom functions: (layout, params, ctx) -> layout; custom_delivery: (transfers, params, ctx, aws) -> results
"""
from __future__ import annotations

KIND = 'destination'

STEPS = [{'id': 'compute_sas_keys',
  'op': 'custom',
  'title': 'Decide target key per file from folder path (7 rules, exactly one must match, else error/)',
  'params': {'function': 'compute_sas_keys'}},
 {'id': 'deliver_move_with_tag',
  'op': 'custom_delivery',
  'title': 'Move each file in the bucket (server-side copy, check, delete source), tag target, report',
  'params': {'function': 'deliver_move_with_tag'}}]


def compute_sas_keys(layout, params, ctx):
    keys = layout.setdefault("keys", {})
    vs = layout.setdefault("vars", {})
    for path in layout.get("files", []):
        if keys.get(path) is not None:
            continue
        segs = path.split('/')
        study = segs[0]
        fname = segs[-1]
        fsegs = segs[:-1] if len(segs) > 1 else [study]
        folder = '/'.join(fsegs)
        last = fsegs[-1]
        P = '/' + folder + '/'
        if '/adam/' in P:
            fmt = 'adam'
        elif '/sdtm/' in P:
            fmt = 'sdtm'
        elif 'raw/' in P:
            fmt = 'raw'
        else:
            fmt = None
        if '_adam_' in last:
            afmt = 'adam'
        elif '_sdtm_' in last:
            afmt = 'sdtm'
        elif '_raw_' in last or '_restricted_raw_' in last:
            afmt = 'raw'
        else:
            afmt = None
        matches = []  # (name, key or None, error or None)
        dr = '/data_reuse/' in P
        # 1 CDAP
        if dr and '/cdap_' in P and fmt:
            if '/cdap_csr' in P:
                matches.append(('CDAP', '/'.join([study, 'extended_primary_use', 'primary', fmt, fname]), None))
            elif '_ia' in last:
                parts = last.split('_')
                if len(parts) < 3:
                    matches.append(('CDAP', None, 'CDAP: too few parts in folder name'))
                else:
                    p = parts[2]
                    if p.startswith('ia'):
                        matches.append(('CDAP', '/'.join([study, 'extended_primary_use', 'interim', fmt, 'ia_' + p[2:], fname]), None))
                    else:
                        matches.append(('CDAP', None, 'CDAP: third part is not an ia value'))
            else:
                parts = last.split('_')
                if len(parts) < 2:
                    matches.append(('CDAP', None, 'CDAP: too few parts in folder name'))
                else:
                    matches.append(('CDAP', '/'.join([study, 'extended_primary_use', 'other', fmt, parts[1], fname]), None))
        # 2 IDAP
        if dr and '/idap' in P and fmt:
            matches.append(('IDAP', '/'.join([study, 'internal_reuse', fmt, last, fname]), None))
        # 3 MED
        if dr and '/med' in P and fmt:
            matches.append(('MED', '/'.join([study, 'external_reuse', fmt, last, fname]), None))
        # 4 ANON
        if '_anon_' in P and afmt:
            if '_anon_csr' in P:
                matches.append(('ANON', '/'.join([study, 'anonymised', 'primary', afmt, fname]), None))
            else:
                u = last.split('_')[-1]
                if u.startswith('ia'):
                    matches.append(('ANON', '/'.join([study, 'anonymised', 'interim', afmt, 'ia_' + u[2:], fname]), None))
                else:
                    matches.append(('ANON', '/'.join([study, 'anonymised', 'other', afmt, u, fname]), None))
        # 5 CDAR
        if '/cdar/' in P and fmt:
            low = [s.lower() for s in fsegs]
            if 'ar' not in low:
                matches.append(('CDAR', None, 'CDAR: no ar folder'))
            else:
                i = low.index('ar')
                if i + 1 >= len(low):
                    matches.append(('CDAR', None, 'CDAR: no reporting level after ar'))
                else:
                    level = low[i + 1]
                    if level in ('adam', 'sdtm', 'raw'):
                        matches.append(('CDAR', None, 'CDAR: reporting level is a data format'))
                    elif level == 'csr':
                        matches.append(('CDAR', '/'.join([study, 'primary', 'complete', fmt, fname]), None))
                    elif level.startswith('ia'):
                        x = level[2:].lstrip('_')
                        matches.append(('CDAR', '/'.join([study, 'primary', 'interim', fmt, 'ia_' + x, fname]), None))
                    else:
                        matches.append(('CDAR', '/'.join([study, 'primary', 'other', fmt, level, fname]), None))
        # 6 OTHERS
        if dr and fmt and not any(t in P for t in ('/med', '/cdap', '/idap', '/anon', '_anon_')):
            matches.append(('OTHERS', '/'.join([study, 'other', fmt, last, fname]), None))
        # 7 DEFAULT
        if not any(t in P for t in ('/data_reuse/', '_anon_', '/cdar/')):
            matches.append(('DEFAULT', path, None))
        if len(matches) == 1 and matches[0][1] is not None:
            keys[path] = matches[0][1]
            vs['rule:' + path] = matches[0][0]
        else:
            keys[path] = 'error/' + path
            if not matches:
                vs['rule:' + path] = 'no rule matched'
            elif len(matches) > 1:
                vs['rule:' + path] = 'multiple rules matched: ' + ','.join(m[0] for m in matches)
            else:
                vs['rule:' + path] = matches[0][2]
    return layout


def deliver_move_with_tag(transfers, params, ctx, aws):
    delivery = ctx.get("delivery") or {}
    sse = delivery.get("server_side_encryption")
    kms = delivery.get("kms_key_id")
    out = {}
    copied = []
    any_failed = False

    def log(t, reason, status, detail):
        aws.log.info("%s -> %s [%s] %s %s" % (t["source_key"], t["target_key"], reason, status, detail))

    def mk(t, status, detail=""):
        return {"path": t["path"], "key": t["target_key"], "status": status, "detail": detail}

    for i, t in enumerate(transfers):
        src_b, src_k = t["source_bucket"], t["source_key"]
        dst_b, dst_k = t["target_bucket"], t["target_key"]
        reason = params.get("rule:" + t["path"], "") or ""
        if dst_k == src_k and dst_b == src_b:
            out[i] = mk(t, "skipped", "already in place")
            log(t, reason, "skipped", "already in place")
            continue
        extra = {}
        if t.get("etag"):
            extra["CopySourceIfMatch"] = t["etag"]
        if sse:
            extra["ServerSideEncryption"] = sse
            if kms:
                extra["SSEKMSKeyId"] = kms
        try:
            exists = False
            try:
                aws.s3_destination.head_object(Bucket=dst_b, Key=dst_k)
                exists = True
            except Exception:
                exists = False
            if exists:
                aws.s3_destination.delete_object(Bucket=dst_b, Key=dst_k)
            aws.s3_destination.copy(
                CopySource={"Bucket": src_b, "Key": src_k},
                Bucket=dst_b, Key=dst_k,
                ExtraArgs=extra, SourceClient=aws.s3_source)
        except Exception as e:
            any_failed = True
            out[i] = mk(t, "failed", "copy failed: %s" % e)
            log(t, reason, "failed", out[i]["detail"])
            continue
        try:
            length = aws.s3_destination.head_object(Bucket=dst_b, Key=dst_k)["ContentLength"]
        except Exception as e:
            any_failed = True
            out[i] = mk(t, "failed", "check failed: %s" % e)
            log(t, reason, "failed", out[i]["detail"])
            continue
        if length != t["size"]:
            any_failed = True
            out[i] = mk(t, "failed", "check failed: size mismatch")
            log(t, reason, "failed", out[i]["detail"])
            continue
        copied.append((i, t, reason))

    for i, t, reason in copied:
        src_b, src_k = t["source_bucket"], t["source_key"]
        dst_b, dst_k = t["target_bucket"], t["target_key"]
        detail = reason
        if not any_failed:
            try:
                aws.s3_source.delete_object(Bucket=src_b, Key=src_k)
            except Exception as e:
                out[i] = mk(t, "failed", "delete of source failed: %s" % e)
                log(t, reason, "failed", out[i]["detail"])
                continue
        else:
            detail = (reason + "; " if reason else "") + "source kept, retried next run"
        if dst_k.startswith("error/"):
            out[i] = mk(t, "moved_to_error", detail)
            log(t, reason, "moved_to_error", detail)
            continue
        try:
            aws.s3_destination.put_object_tagging(
                Bucket=dst_b, Key=dst_k,
                Tagging={"TagSet": [{"Key": "ADDITIONAL_TAG", "Value": t["path"]}]})
        except Exception as e:
            aws.log.warning("tagging failed for %s: %s" % (dst_k, e))
            detail = (detail + "; " if detail else "") + "tagging failed"
        out[i] = mk(t, "moved", detail)
        log(t, reason, "moved", detail)

    return [out[i] for i in range(len(transfers))]


CUSTOM = {"compute_sas_keys": compute_sas_keys, "deliver_move_with_tag": deliver_move_with_tag}
